def min_points(intervals):
    if not intervals:
        return 0
    sorted_intervals = sorted(intervals, key=lambda x: x[1])
    count = 0
    last_point = -float('inf')
    for start, end in sorted_intervals:
        if start > last_point:
            count += 1
            last_point = end
    return count
